{(event) => {
                  setLinkEditor((current) => current ? { ...current, url: event.target.value } : current);
                  if (linkError) setLinkError(normalizeLink(event.target.value) ? undefined : "Enter a valid website or email link.");
                }}

sourceInventory.onKeyDown:
{(event) => {
            if (event.key === "Enter" || event.key === ",") {
              event.preventDefault();
              addDraft();
            } else if (event.key === "Backspace" && !draft && value.length) {
              onChange(value.slice(0, -1));
            }
          }}

sourceInventory.onChange:
{(event) => {
          const input = event.target.value; setScoreInput(input);
          const score = Number(input);
          if (!Number.isFinite(score) || score < 0 || score > 100) { setScoreError("Enter a score between 0 and 100."); return; }
          setScoreError(undefined); setMinScore(score); setPage(1);
        }}

