            if (value === "SINGLE_SCHOOL") {
              updateField("trustName", "");
              updateField("trustCompanyNumber", "");
              updateField("signatoryName", "");
              updateField("signatoryEmail", "");
              updateField("signatoryJobTitle", "");
            }
